def find_pluses(g):
    h,w=len(g),len(g[0]); out=[]
    for r in range(1,h-1):
        for c in range(1,w-1):
            if g[r][c]==2 and all(g[r+dr][c+dc]==3 for dr in(-1,0,1) for dc in(-1,0,1) if (dr,dc)!=(0,0)):
                out.append((r,c))
    return out

def find_lines(g, plus_cells):
    h,w=len(g),len(g[0])
    def is_line(cells):
        return all(v==2 or (i in plus_cells) for i,v in cells)
    vlines=[j for j in range(w) if is_line([((i,j),g[i][j]) for i in range(h)])]
    hlines=[i for i in range(h) if is_line([((i,j),g[i][j]) for j in range(w)])]
    return vlines,hlines

def transform(g):
    h,w=len(g),len(g[0])
    pluses=find_pluses(g)
    pcells={(r+dr,c+dc) for r,c in pluses for dr in(-1,0,1) for dc in(-1,0,1)}
    vlines,hlines=find_lines(g,pcells)
    out=[row[:] for row in g]
    vertical=len(vlines)>=len(hlines)
    lines = vlines if vertical else hlines
    stamps=set()
    for r,c in pluses:
        own = c if vertical else r
        for L in lines:
            if L==own: continue
            rr,cc = (r,L) if vertical else (L,c)
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    v = 2 if (dr,dc)==(0,0) else 1
                    out[rr+dr][cc+dc]=v
                    if v==2: stamps.add((rr+dr,cc+dc))
    for r,c in pluses:
        if vertical:
            for j in range(w):
                if out[r][j]==0: out[r][j]=1
        else:
            for i in range(h):
                if out[i][c]==0: out[i][c]=1
    return out

